import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, float, mix, uniform, screenUV } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader('/prism-mock/home/nodes/orb-decor.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const inkColor = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surfaceColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);

  const uvNode = uv();
  const gradientMix = uniform(0.5);

  // engineered gradient surface: linear blend from ink to surface based on vertical uv
  const gradient = mix(surfaceColor, inkColor, uvNode.y);

  let colorNode;
  if (map) {
    const texColor = texture(map, uvNode);
    colorNode = mix(vec4(gradient, 1.0), texColor, texColor.a);
  } else {
    colorNode = vec4(gradient, 1.0);
  }

  // subtle grain using screen-space uv hashed noise approximation
  const grainSeed = screenUV.mul(1000.0);
  const grainNoise = grainSeed.x.sin().mul(grainSeed.y.cos()).fract().sub(0.5).mul(0.03);
  const grained = colorNode.add(vec4(grainNoise, grainNoise, grainNoise, 0.0));

  material.colorNode = grained;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.name = 'hub-collection-card-1-decor';

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
